import yaml, os

class YAMLCache:
    def __init__(self):
        self.cache_dir = "/tmp/yaml_cache"

    def get(self, key):
        path = os.path.join(self.cache_dir, f"{key}.yaml")
        if os.path.exists(path):
            with open(path, 'r') as f:
                return yaml.load(f, Loader=yaml.Loader)
        return None

    def set(self, key, data):
        path = os.path.join(self.cache_dir, f"{key}.yaml")
        with open(path, 'w') as f:
            yaml.dump(data, f)
